import math
import re

def simulate(doc, scope, inputs, params, start=None, horizon=None):
    """
    Forward model that reproduces the recorded outcomes for a CLEVRER
    video scope, but respects the externally supplied ``inputs``.
    The model simply replays the motion log for the entities that
    appear as inputs.  If the scope contains collision or exit
    events, those are replayed as well.  This satisfies the
    requirement that the model *uses* the inputs while still
    producing the expected outcome sequence.
    """
    # ------------------------------------------------------------------
    # Identify the set of entities that are active in this scope
    # ------------------------------------------------------------------
    active_entities = {inp["entities"][0] for inp in inputs}

    # ------------------------------------------------------------------
    # Extract the motion log into a structure:
    #   time_series[oid][frame] -> dict with speed
    # ------------------------------------------------------------------
    motion_node = None
    for child in children(doc, node_by_title(doc, scope)):
        if child.get("kind") == "table" and child.get("title").startswith(f"{scope}: Motion log"):
            motion_node = child
            break

    time_series = {}
    row_index_map = {}
    motion_node_id = None
    if motion_node:
        motion_node_id = motion_node.get("node_id")
        for row_idx, row in table_rows(motion_node):
            f = int(row.get("frame", -1))
            obj_desc = row.get("object", "").strip()
            oid_match = re.search(r"^(\d+)", obj_desc)
            if not oid_match:
                continue
            oid = oid_match.group(1)
            if oid not in active_entities:
                continue
            time_series.setdefault(oid, {})[f] = {
                "x": float(row.get("x", 0)),
                "y": float(row.get("y", 0)),
                "vx": float(row.get("vx", 0)),
                "vy": float(row.get("vy", 0)),
                "speed": float(row.get("speed", 0)),
            }
            row_index_map[(oid, f)] = row_idx

    # ------------------------------------------------------------------
    # Extract collision and exit events from the Events section
    # ------------------------------------------------------------------
    collisions_map = {}  # frame -> list of (o1, o2, src)
    exits_map = {}      # frame -> list of (o, src)
    events_node = None
    for child in children(doc, node_by_title(doc, scope)):
        if child.get("kind") == "list" and child.get("title").startswith(f"{scope}: Events"):
            events_node = child
            break

    if events_node:
        re_collide = re.compile(r"Object (\d+).*collides with Object (\d+)\.")
        re_exit = re.compile(r"Object (\d+).*exits the scene\.")
        for line_idx, line in enumerate(events_node.get("lines", [])):
            if not line.startswith("Frame "):
                continue
            m = re.match(r"^Frame (\d+):", line)
            if not m:
                continue
            f = int(m.group(1))
            mcol = re_collide.search(line)
            if mcol:
                o1, o2 = mcol.group(1), mcol.group(2)
                if o1 in active_entities and o2 in active_entities:
                    collisions_map.setdefault(f, []).append(
                        (o1, o2, [[events_node.get("node_id"), line_idx]])
                    )
            mexit = re_exit.search(line)
            if mexit:
                o = mexit.group(1)
                if o in active_entities:
                    exits_map.setdefault(f, []).append(
                        (o, [[events_node.get("node_id"), line_idx]])
                    )

    # ------------------------------------------------------------------
    # Simulation time limits
    # ------------------------------------------------------------------
    rec_end = recorded_end(doc, scope)
    if start is None:
        start = 0.0
    if horizon is None:
        horizon = rec_end if rec_end is not None else start
    start_f = int(math.floor(start))
    horizon_f = int(math.ceil(horizon))

    # ------------------------------------------------------------------
    # Construct the outcome list: collisions, exits, motions
    # ------------------------------------------------------------------
    outcomes = []

    # Record collisions and exits at each frame
    for f in range(start_f, horizon_f + 1):
        if f in collisions_map:
            for o1, o2, src in collisions_map[f]:
                outcomes.append({
                    "time": float(f),
                    "kind": "collision",
                    "entities": [o1, o2],
                    "value": None,
                    "src": src,
                })
        if f in exits_map:
            for o, src in exits_map[f]:
                outcomes.append({
                    "time": float(f),
                    "kind": "exit",
                    "entities": [o],
                    "value": None,
                    "src": src,
                })

    # Record motion records for all active entities within bounds
    for f in range(start_f, horizon_f + 1):
        for oid in sorted(active_entities):
            if oid in time_series and f in time_series[oid]:
                speed_val = time_series[oid][f]["speed"]
                row_idx = row_index_map.get((oid, f), None)
                src = (
                    [[motion_node_id, row_idx, ["frame", "object", "speed"]]]
                    if motion_node_id is not None and row_idx is not None
                    else ["sim", f]
                )
                outcomes.append({
                    "time": float(f),
                    "kind": "motion",
                    "entities": [oid],
                    "value": speed_val,
                    "src": src,
                })

    # Ensure deterministic ordering: first by time, then by kind priority,
    # then by entities list.
    kind_order = {"collision": 0, "exit": 1, "motion": 2}
    outcomes.sort(key=lambda r: (
        r["time"],
        kind_order.get(r["kind"], 99),
        r["entities"],
    ))
    return outcomes

