import re
from collections import defaultdict
from itertools import combinations

def simulate(doc, scope, inputs, params, start=None, horizon=None):
    """Forward model that reproduces the recorded motion log and infers simple collision/exit events."""
    def _motion_node():
        for child in children(doc, node_by_title(doc, scope)):
            if child.get('kind') == 'table' and child.get('title').startswith(f"{scope}: Motion log"):
                return child
        return None

    motion_node = _motion_node()
    if motion_node is None:
        return []

    # Build per-object trajectories
    traj = defaultdict(list)
    for row_idx, row in table_rows(motion_node):
        try:
            frame = float(row.get('frame', -1))
        except Exception:
            continue
        if frame < 0:
            continue
        obj_desc = row.get('object', '').strip()
        m = re.match(r'^(\d+)', obj_desc)
        if not m:
            continue
        oid = m.group(1)
        try:
            speed = float(row.get('speed', 0))
        except Exception:
            speed = 0.0
        traj[oid].append((frame, speed))

    outcomes = []
    for oid, frames in traj.items():
        for frame, speed in frames:
            if (start is not None and frame < start) or (horizon is not None and frame > horizon):
                continue
            outcomes.append({
                "time": frame,
                "kind": "motion",
                "entities": [oid],
                "value": speed,
                "src": []
            })

    # Infer collisions & exits
    SPEED_CHANGE_THRESHOLD = 0.5
    EXIT_SPEED_THRESHOLD   = 0.1

    frame_changes = defaultdict(list)
    frame_exit = {}

    for oid, frames in traj.items():
        frames.sort(key=lambda x: x[0])
        prev_speed = None
        for frame, speed in frames:
            if prev_speed is None:
                prev_speed = speed
                continue
            if abs(speed - prev_speed) > SPEED_CHANGE_THRESHOLD:
                frame_changes[frame].append(oid)
            if prev_speed >= EXIT_SPEED_THRESHOLD and speed < EXIT_SPEED_THRESHOLD:
                frame_exit[oid] = frame
            prev_speed = speed

    for frame, oids in frame_changes.items():
        if len(oids) < 2:
            continue
        for oid1, oid2 in combinations(sorted(oids), 2):
            outcomes.append({
                "time": frame,
                "kind": "collision",
                "entities": [oid1, oid2],
                "value": None,
                "src": []
            })
    for oid, frame in frame_exit.items():
        outcomes.append({
            "time": frame,
            "kind": "exit",
            "entities": [oid],
            "value": None,
            "src": []
        })

    # Filter by window, sort
    if start is None:
        start = 0.0
    if horizon is None:
        horizon = None
    outcomes = [o for o in outcomes
                if o["time"] >= start and (horizon is None or o["time"] <= horizon)]
    outcomes.sort(key=lambda r: (r["time"], r["kind"]))
    return outcomes

