import re
from typing import List, Dict, Any, Tuple

# Helpers are provided in the environment
# node_by_title(doc, title)
# node_by_id(doc, node_id)
# children(doc, node)
# scope_nodes(doc, scope)
# table_rows(node) -> [(row_index, {column: cell})]

def entities(doc: Dict[str, Any], scope: str) -> List[Dict[str, str]]:
    """Return list of entities for the given scope."""
    scope_node = node_by_title(doc, scope)
    ents: List[Dict[str, str]] = []

    for child in children(doc, scope_node):
        if child.get('kind') == 'list' and child.get('title').startswith(f"{scope}: Objects"):
            # lines format: 'Object 0: gray rubber cylinder (color=gray, material=rubber, shape=cylinder)'
            for line in child.get('lines', []):
                m = re.match(r'^Object (\d+): ([^(]+)', line)
                if m:
                    obj_id, description = m.group(1).strip(), m.group(2).strip()
                    ents.append({"id": obj_id, "description": description})
    return ents


def recorded_end(doc: Dict[str, Any], scope: str) -> float or None:
    """Return the last recorded frame in the scope."""
    scope_node = node_by_title(doc, scope)
    max_frame = None

    for child in children(doc, scope_node):
        if child.get('kind') == 'list' and child.get('title').startswith(f"{scope}: Events"):
            for line in child.get('lines', []):
                m = re.match(r'^Frame (\d+):', line)
                if m:
                    f = int(m.group(1))
                    max_frame = f if max_frame is None else max(max_frame, f)
        if child.get('kind') == 'table' and child.get('title').startswith(f"{scope}: Motion log"):
            for idx, row in table_rows(child):
                f = int(row.get('frame', -1))
                max_frame = f if max_frame is None else max(max_frame, f)
    return max_frame


# ---------- Inputs ----------
def _extract_object_id(text: str) -> str:
    """Return the object id from a line fragment like 'Object 0 (gray rubber cylinder)'."""
    m = re.search(r'Object (\d+)', text)
    return m.group(1) if m else None


def inputs(doc: Dict[str, Any], scope: str) -> List[Dict[str, Any]]:
    """Return list of inputs for the given scope."""
    scope_node = node_by_title(doc, scope)
    inputs_list: List[Dict[str, Any]] = []
    events_node = None
    obj_map = {e['id']: e for e in entities(doc, scope)}  # for validation

    # Find the Events node
    for child in children(doc, scope_node):
        if child.get('kind') == 'list' and child.get('title').startswith(f"{scope}: Events"):
            events_node = child
            break

    if events_node is None:
        return inputs_list  # no events -> no inputs

    # Regular expressions
    re_frame = re.compile(r'^Frame (\d+):')
    re_present = re.compile(r'Object (\d+)\s+\(.*\)\s+is in view when the video begins\.')
    re_enter = re.compile(r'Object (\d+)\s+\(.*\)\s+enters the scene\.')
    # Process lines
    for line_idx, line in enumerate(events_node.get('lines', [])):
        frame_m = re_frame.match(line)
        if not frame_m:
            continue
        frame = int(frame_m.group(1))
        if frame == 0:
            # appearance – object in view at start
            m = re_present.search(line)
            if m:
                oid = m.group(1)
                if oid in obj_map:
                    src = [[events_node.get('node_id'), line_idx]]
                    inputs_list.append({
                        "id": f"appearance-{oid}",
                        "time": float(frame),
                        "kind": "appearance",
                        "entities": [oid],
                        "fields": {"description": obj_map[oid]["description"]},
                        "src": src
                    })
        else:
            # others – entering scene
            m = re_enter.search(line)
            if m:
                oid = m.group(1)
                if oid in obj_map:
                    src = [[events_node.get('node_id'), line_idx]]
                    inputs_list.append({
                        "id": f"enter-{oid}",
                        "time": float(frame),
                        "kind": "enter",
                        "entities": [oid],
                        "fields": {"description": obj_map[oid]["description"]},
                        "src": src
                    })
    return inputs_list


# ---------- Outcomes ----------
def outcomes(doc: Dict[str, Any], scope: str) -> List[Dict[str, Any]]:
    """Return list of outcomes for the given scope."""
    scope_node = node_by_title(doc, scope)
    outcomes_list: List[Dict[str, Any]] = []
    events_node = None
    motion_node = None
    obj_map = {e['id']: e for e in entities(doc, scope)}

    # Find nodes
    for child in children(doc, scope_node):
        if child.get('kind') == 'list' and child.get('title').startswith(f"{scope}: Events"):
            events_node = child
        if child.get('kind') == 'table' and child.get('title').startswith(f"{scope}: Motion log"):
            motion_node = child

    # Process event lines for collisions and exits
    if events_node:
        re_frame = re.compile(r'^Frame (\d+):')
        re_collide = re.compile(r'Object (\d+).*collides with Object (\d+)\.')
        re_exit = re.compile(r'Object (\d+).*exits the scene\.')
        for line_idx, line in enumerate(events_node.get('lines', [])):
            frame_m = re_frame.match(line)
            if not frame_m:
                continue
            frame = int(frame_m.group(1))
            # Collision
            m = re_collide.search(line)
            if m:
                oid1, oid2 = m.group(1), m.group(2)
                src = [[events_node.get('node_id'), line_idx]]
                outcomes_list.append({
                    "time": float(frame),
                    "kind": "collision",
                    "entities": [oid1, oid2],
                    "value": None,
                    "src": src
                })
            # Exit
            m = re_exit.search(line)
            if m:
                oid = m.group(1)
                src = [[events_node.get('node_id'), line_idx]]
                outcomes_list.append({
                    "time": float(frame),
                    "kind": "exit",
                    "entities": [oid],
                    "value": None,
                    "src": src
                })

    # Process motion log rows
    if motion_node:
        for row_idx, row in table_rows(motion_node):
            frame = float(row.get('frame', '0'))
            obj_desc = row.get('object', '').strip()
            # object description is like '1 red metal cylinder'
            obj_id_match = re.search(r'^(\d+)', obj_desc)
            if not obj_id_match:
                continue
            oid = obj_id_match.group(1)
            if oid not in obj_map:
                continue
            speed = row.get('speed')
            try:
                speed_val = float(speed)
            except Exception:
                speed_val = None
            src = [[motion_node.get('node_id'), row_idx, ['frame', 'object', 'speed']]]
            outcomes_list.append({
                "time": float(frame),
                "kind": "motion",
                "entities": [oid],
                "value": speed_val,
                "src": src
            })

    return outcomes_list


# ---------- Parameters ----------
def params(doc: Dict[str, Any], scope: str) -> Dict[str, Any]:
    """Return any constants found in the scope. Empty for CLEVRER docs."""
    return {}


