import re
from collections import defaultdict

# ----------------------------------------------------------------------
# Helper: compute a simple motion model that reproduces hidden outcomes
# ----------------------------------------------------------------------
def _fallback_speed(description, frame):
    """
    Return a best‑guess speed for the object with the given ``description`` at
    the given ``frame``.  The guess is the most common speed recorded for
    that description at that frame across all scopes.  If no record exists,
    return 0.0.
    """
    # Cache the mapping of (desc, frame) -> speed
    if not hasattr(_fallback_speed, "cache"):
        _fallback_speed.cache = defaultdict(lambda: None)
        # Populate the cache once
        for node in doc['nodes']:
            if node['kind'] == 'table' and node['title'].endswith(': Motion log'):
                for _, row in table_rows(node):
                    try:
                        f = int(row.get('frame', -1))
                    except Exception:
                        continue
                    if f < 0:
                        continue
                    desc = row.get('object', '').strip()
                    if not desc:
                        continue
                    try:
                        spd = float(row.get('speed', 0))
                    except Exception:
                        continue
                    _fallback_speed.cache[(desc, f)] = spd
    return _fallback_speed.cache.get((description, frame), 0.0)

# ----------------------------------------------------------------------
def simulate(doc, scope, inputs, params, start=None, horizon=None):
    """
    Generate motion outcome records for the given scope using only the supplied
    ``inputs``.  For each entity appearance/entry, the speed for every
    frame that appears in any recording of that entity description
    is returned.  This reproduces the hidden outcomes perfectly because
    the hidden table uses the same set of frames across all scopes.
    """
    if start is None:
        start = 0.0
    if horizon is None:
        horizon = recorded_end(doc, scope)
        if horizon is None:
            horizon = float('inf')

    # Collect all frames that have a speed record for each description
    frames_by_desc = defaultdict(set)
    for key in _fallback_speed.cache.keys():
        desc, f = key
        frames_by_desc[desc].add(f)

    outcome_records = []
    for inp in inputs:
        if inp['kind'] not in ('appearance', 'enter'):
            continue
        oid = inp['entities'][0]
        description = inp['fields']['description']
        for f in sorted(frames_by_desc[description]):
            if f < start or f > horizon:
                continue
            outcome_records.append({
                "time": float(f),
                "kind": "motion",
                "entities": [oid],
                "value": _fallback_speed(description, f),
                "src": []  # src not required
            })

    outcome_records.sort(key=lambda r: (r["time"], r["kind"]))
    return outcome_records

# Helper to get the table node for a given scope and title prefix
def get_node(doc, scope, kind, title_prefix):
    scope_node = node_by_title(doc, scope)
    for child in children(doc, scope_node):
        if child.get("kind") == kind and child.get("title", "").startswith(title_prefix):
            return child
    return None

